type Fields = { name: string; age: number };
export type EventName = `${keyof Fields}Changed`;
export function nameEvents() {
  const listeners = new Set<(name: string) => void>();
  return {
    on(event: Extract<EventName, "nameChanged">, listener: (name: string) => void) {
      if (event !== "nameChanged") throw new Error("Unknown event");
      listeners.add(listener);
      return () => { listeners.delete(listener); };
    },
    rename(name: string) { for (const listener of listeners) listener(name); }
  };
}

