export async function summarize(tasks: readonly Promise<string>[]) {
  const outcomes = await Promise.allSettled(tasks);
  return {
    values: outcomes.flatMap(result => result.status === "fulfilled" ? [result.value] : []),
    errors: outcomes.flatMap(result => result.status === "rejected" ? [String(result.reason)] : [])
  };
}

export async function ownedBatch<T>(jobs: readonly ((signal: AbortSignal) => Promise<T>)[]): Promise<T[]> {
  const owner = new AbortController();
  const tasks = jobs.map(job => Promise.resolve().then(() => job(owner.signal)));
  try { return await Promise.all(tasks); }
  catch (error) {
    owner.abort();
    await Promise.allSettled(tasks);
    throw error;
  }
}

