export type FormState = { name: string; error: string; saved: string };
export type FormAction = { type: "edit"; value: string } | { type: "submit" } | { type: "reset" };
export const initial: FormState = { name: "", error: "", saved: "" };
export function reducer(state: FormState, action: FormAction): FormState {
  switch (action.type) {
    case "edit": return { ...state, name: action.value, error: "" };
    case "submit": return state.name.trim() ? { ...state, saved: state.name.trim(), error: "" } : { ...state, error: "Name required" };
    case "reset": return initial;
  }
}
export function NameForm() {
  const [state, dispatch] = useReducer(reducer, initial);
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); dispatch({ type: "submit" }); }
  return <form onSubmit={submit}><input aria-label="Name" value={state.name} onChange={e => dispatch({ type: "edit", value: e.currentTarget.value })} /><button>Save</button><button type="button" onClick={() => dispatch({ type: "reset" })}>Reset</button><p role="status">{state.error || state.saved}</p></form>;
}

import { useReducer } from "react";
type State = { current: string; past: readonly string[] };
type Action = { type: "edit"; text: string } | { type: "undo" };
export function history(state: State, action: Action): State {
  if (action.type === "edit") return action.text === state.current ? state : { current: action.text, past: [...state.past, state.current] };
  if (!state.past.length) return state;
  return { current: state.past[state.past.length - 1]!, past: state.past.slice(0, -1) };
}
export function Draft() {
  const [state, dispatch] = useReducer(history, { current: "", past: [] });
  return <><input aria-label="Draft" value={state.current} onChange={e => dispatch({ type: "edit", text: e.currentTarget.value })} /><button disabled={!state.past.length} onClick={() => dispatch({ type: "undo" })}>Undo</button></>;
}

