  return <ThemeContext.Provider value={{ theme, toggle: () => setTheme(t => t === "light" ? "dark" : "light") }}>{children}</ThemeContext.Provider>;
}
export function ThemeButton() { const { theme, toggle } = useTheme(); return <button onClick={toggle}>{theme}</button>; }

import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
export type StatusSource = { subscribe(listener: (status: string) => void): () => void };
const SourceContext = createContext<StatusSource | null>(null);
export function StatusProvider({ source, children }: { source: StatusSource; children: ReactNode }) {
  return <SourceContext.Provider value={source}>{children}</SourceContext.Provider>;
}
export function Status() {
  const source = useContext(SourceContext);
  if (!source) throw new Error("StatusProvider required");
  const [status, setStatus] = useState("waiting");
  useEffect(() => { setStatus("waiting"); return source.subscribe(setStatus); }, [source]);
  return <p role="status">{status}</p>;
}

import { z } from "zod";
export const Profile = z.object({ name: z.string().trim().min(1), age: z.number().int().min(0) });
export function validateProfile(input: unknown) {
  const result = Profile.safeParse(input);
  if (result.success) return { ok: true as const, data: result.data };
  return { ok: false as const, issues: result.error.issues.map(issue => ({ field: issue.path.join("."), message: issue.message, code: issue.code })) };
}

import { z } from "zod";
export const Range = z.object({ start: z.number().finite(), end: z.number().finite() })
  .refine(value => value.end >= value.start, { path: ["end"], message: "End precedes start" });
export function validateRange(input: unknown) { return Range.safeParse(input); }

import express, { type ErrorRequestHandler } from "express";
import { z } from "zod";
export const app = express();
const User = z.object({ name: z.string().trim().min(1) }).strict();
app.use(express.json({ limit: "1kb" }));
app.post("/users", (req, res) => {
  const result = User.safeParse(req.body);
  if (!result.success) { res.status(422).json({ error: "Invalid user", fields: result.error.issues.map(issue => issue.path.join(".")) }); return; }
  res.status(201).json(result.data);
});
const errors: ErrorRequestHandler = (error, req, res, next) => {
  if (res.headersSent) return next(error);
  const status = error?.type === "entity.parse.failed" ? 400 : error?.type === "entity.too.large" ? 413 : 500;
  res.status(status).json({ error: status === 500 ? "Request failed" : "Invalid JSON body" });
};
app.use(errors);

import express, { type ErrorRequestHandler } from "express";
export function createApp(load: (id: string) => Promise<string | undefined>) {
  const app = express();
  app.get("/items/:id", async (req, res) => {
    const value = await load(req.params.id);
    if (value === undefined) { res.status(404).json({ error: "Not found" }); return; }
    res.json({ value });
  });
  const errors: ErrorRequestHandler = (error, req, res, next) => {
    if (res.headersSent) return next(error);
    res.status(503).json({ error: "Try again" });
  };
  app.use(errors);
  return app;
}

import { useQuery } from "@tanstack/react-query";
export function Items({ load }: { load: (signal: AbortSignal) => Promise<string[]> }) {
  const query = useQuery({ queryKey: ["depth-items"], queryFn: ({ signal }) => load(signal), retry: false });
  if (query.isPending) return <p role="status">Loading</p>;
  if (query.isError) return <button onClick={() => { void query.refetch(); }}>Retry</button>;
  return <p role="status">{query.data.length ? query.data.join(", ") : "No items"}</p>;
}

import { useQuery } from "@tanstack/react-query";
export function CachedItems({ load }: { load: (signal: AbortSignal) => Promise<string[]> }) {
  const query = useQuery({ queryKey: ["depth-cached"], queryFn: ({ signal }) => load(signal), retry: false });
  if (query.data === undefined) return <p role="status">{query.isError ? "Unavailable" : "Loading"}</p>;
  return <><p role="status">{query.data.length} cached items{query.isFetching ? " (refreshing)" : ""}</p>{query.isError && <p role="alert">Refresh failed</p>}<button onClick={() => { void query.refetch(); }}>Refresh</button></>;
}
